#addr 0x0400
main:
    ld 0x60, ac
    ld ac, [0x14]             ; clear pages 60..FF
clr_pg:
    ld [0x14], y
    ld 0, ac
clr_in:
    ld ac, x
    ld 0, [y,x]
    inc
    bne clr_in
    ld [0x14], ac
    inc
    ld ac, [0x14]
    bne clr_pg
    ld 0x5A, y                ; mode byte of every row = 3 (8 bpp), x5A20-x5BFF
    ld 0x20, ac
mode1:
    ld ac, x
    ld 3, [y,x]
    inc
    bne mode1
    ld 0x5B, y
mode2:
    ld ac, x
    ld 3, [y,x]
    inc
    bne mode2
    ld 0, ac
    ld ac, [0x18]
    ld ac, [0x17]
pend_loop:
    ld [0x17], ac             ; draw every valid cell grey
    add 0x20, ac
    ld ac, x
    ld 0x03, y
    ld [y,x], ac
    ld ac, [0x10]
    ld 0, ac
    ld ac, [0x19]
    ld pend_ret & 0xFF, ac
    ld ac, [0x12]
    ld pend_ret >> 8, ac
    ld ac, [0x13]
    ld draw >> 8, y
    jmp draw
pend_ret:
    ld [0x17], ac
    inc
    ld ac, [0x17]
    xor 187, ac
    bne pend_loop
    ld t00 >> 8, y
    jmp t00
report:
    ld [0x11], ac
    bne rep_fail
    ld 1, ac
    ld ac, [0x19]
    ld draw >> 8, y
    jmp draw
rep_fail:
    ld 2, ac
    ld ac, [0x19]
    ld [0x18], ac
    inc
    ld ac, [0x18]
    ld draw >> 8, y
    jmp draw
draw:
    ld [0x10], ac
    ld ac, x
    ld 0x01, y
    ld [y,x], ac
    ld ac, [0x15]             ; first row (low address byte)
    ld 0x02, y
    ld [y,x], ac
    ld ac, [0x14]             ; first page
    ld 8, ac
    ld ac, [0x16]             ; 8 byte columns
    ld [0x19], ac
    beq draw_c0
    xor 1, ac
    beq draw_c1
    xor 3, ac
    beq draw_c2
    ld fill3 >> 8, y
    jmp fill3
draw_c0:
    ld fill0 >> 8, y
    jmp fill0
draw_c1:
    ld fill1 >> 8, y
    jmp fill1
draw_c2:
    ld fill2 >> 8, y
    jmp fill2
fill0:
    ld [0x14], y
    ld [0x15], ac
    ld ac, x
    ld 0x4A, [y,x]            ; grey
    inc
    ld ac, x
    ld 0x4A, [y,x]
