    ld ac, x
    ld 0x4A, [y,x]
    inc
    ld ac, x
    ld 0x4A, [y,x]
    inc
    ld ac, x
    ld 0x4A, [y,x]
    inc
    ld ac, x
    ld 0x4A, [y,x]
    inc
    ld ac, x
    ld 0x4A, [y,x]
    inc
    ld ac, x
    ld 0x4A, [y,x]
    inc
    ld ac, x
    ld 0x4A, [y,x]
    inc
    ld ac, x
    ld 0x4A, [y,x]
    inc
    ld [0x14], ac
    add 2, ac
    ld ac, [0x14]
    ld [0x16], ac
    add 0xFF, ac
    ld ac, [0x16]
    bne fill0
    ld [0x13], y
    jmp [0x12]                ; return

