#addr 0x0700
hk_poll:
    ld 0x5D, y
    ld 0x00, x
    ld [y,x], ac
    xor 0x4D, ac
    bne hkp_ret
    ld 0x01, x
    ld [y,x], ac
    xor 0x4E, ac
    bne hkp_ret
    ld 0x02, x
    ld [y,x], ac
    xor 0x55, ac
    bne hkp_ret
    ld 0x50, y                ; line read (V9:V2)
    ld [y,x], ac
    ld 0x5D, y
    ld 0x0A, x
    ld ac, [y,x]
    ld 0x06, x
    sub [y,x], ac             ; cur - last - 96 >= 0: a new frame
    sub 96, ac
    ld 0x0A, x
    blt hkp_same
    ld [y,x], ac
    ld 0x06, x
    ld ac, [y,x]
    ld 0x52, y                ; Esc: key column 0, row 0
    ld 0x00, x
    ld 0x0F, [y,x]
    nop
    nop
    nop
    nop
    ld [y,x], ac
    ld 0xFB, [y,x]
    and 1, ac
    beq hkp_esc
    ld 0x5D, y
    ld 0x03, x
    ld [y,x], ac
    bne hkp_ret               ; picked from the menu: no time limit
    ld 0x04, x
    ld [y,x], ac
    dec
    ld ac, [y,x]
    bcc hkp_ret               ; no borrow
    ld 0x05, x
    ld [y,x], ac
    dec
    ld ac, [y,x]
    blt hkp_next              ; below 0: time up
    bra hkp_ret
hkp_same:
    ld [y,x], ac
    ld 0x06, x
    ld ac, [y,x]
hkp_ret:
    ld [0x1F], y
    jmp [0x1E]
hkp_esc:
    ld 1, ac
    bra hkp_go
hkp_next:
    ld 2, ac
hkp_go:
    ld 0x5D, y
    ld 0x09, x
    ld ac, [y,x]
    jmp 0x20                  ; the menu's exit code (RAM x5D20)
hk_done:
    ld 0x5D, y
    ld 0x00, x
    ld [y,x], ac
